const button = document.querySelector("#locate");
const output = document.querySelector("#location");
let watchId;

button.addEventListener("click", () => {
  if (!navigator.geolocation) {
    output.textContent = "Location is not available in this browser.";
    return;
  }
  if (watchId !== undefined) return;
  watchId = navigator.geolocation.watchPosition(
    ({ coords }) => { output.textContent = `${coords.latitude}, ${coords.longitude}`; },
    (error) => { output.textContent = `Location unavailable (${error.code}).`; },
    { maximumAge: 30_000, timeout: 10_000 }
  );
});

function stopWatching() {
  if (watchId === undefined) return;
  navigator.geolocation.clearWatch(watchId);
  watchId = undefined;
}

const copyButton = document.querySelector("#copy-link");
const status = document.querySelector("#copy-status");

copyButton.addEventListener("click", async () => {
  const shareUrl = window.location.href;
  if (!navigator.clipboard?.writeText) {
    status.textContent = "Copy is unavailable; select the address bar URL.";
    return;
  }
  try {
    await navigator.clipboard.writeText(shareUrl);
    status.textContent = "Link copied.";
  } catch {
    status.textContent = "Copy was blocked; copy the link manually.";
  }
});

const notificationButton = document.querySelector("#enable-notifications");
const notificationStatus = document.querySelector("#notification-status");

async function requestSystemNotification() {
  if (!("Notification" in window) || !window.isSecureContext) {
    notificationStatus.textContent = "System notifications are unavailable; use in-page updates.";
    return;
  }

  let permission = Notification.permission;
  if (permission === "default") {
    try {
      permission = await Notification.requestPermission();
    } catch {
      notificationStatus.textContent = "Permission request failed; updates remain available in this page.";
      return;
    }
  }

  if (permission !== "granted") {
    notificationStatus.textContent = permission === "denied"
      ? "Notifications are blocked; check browser settings if you want them."
      : "No notification permission; updates remain available in this page.";
    return;
  }

  try {
    const registration = await navigator.serviceWorker?.getRegistration();
    if (registration) {
      await registration.showNotification("Build completed", {
        body: "Your lesson build is ready.",
        tag: "build-status",
      });
      notificationStatus.textContent = "System notification shown.";
      return;
    }

    // Page notifications work on desktop; most mobile browsers require a Service Worker.
    const notification = new Notification("Build completed", { body: "Your lesson build is ready." });
    notification.addEventListener("click", () => {
      window.focus();
      notification.close();
    });
    notificationStatus.textContent = "System notification shown.";
  } catch {
    notificationStatus.textContent = "System notification unavailable here; check updates in this page.";
  }
}

if (notificationButton && notificationStatus) {
  // Call permission only from this explicit user action.
  notificationButton.addEventListener("click", requestSystemNotification);
}

function disposeNotificationFeature() {
  notificationButton?.removeEventListener("click", requestSystemNotification);
}

const card = document.querySelector(".card");
const observer = new ResizeObserver(([entry]) => {
  const inlineSize = entry.contentBoxSize?.[0]?.inlineSize ?? entry.contentRect.width;
  const compact = inlineSize < 360;
  card.classList.toggle("card--compact", compact);
});
observer.observe(card);

// Call when this card/view is removed:
function disposeCard() {
  observer.unobserve(card);
  observer.disconnect();
}

const video = document.querySelector("#preview-video");
const controls = document.querySelector("#media-controls");

if (video) {
  function syncAnimation() {
    if (document.hidden) video.pause();
    else video.play().catch(() => controls?.classList.add("needs-play"));
  }

  function onVisibilityChange() { syncAnimation(); }
  document.addEventListener("visibilitychange", onVisibilityChange);
  syncAnimation(); // also handle the initial state

  function dispose() {
    document.removeEventListener("visibilitychange", onVisibilityChange);
  }
}

